def trigger_emotional_intervention(user_id, real_time_metrics, historical_data):
    """
    Analyzes real-time signals and historical context to decide on the best intervention.

    Parameters
    ----------
    user_id : str
        Unique identifier for the student.
    real_time_metrics : dict
        Contains:
            - 'typing_speed' : float (characters per minute)
            - 'voice_pitch' : float (Hz) or None (if no voice input)
            - 'sentiment_score' : float (-1.0 to 1.0)
    historical_data : dict
        Contains:
            - 'session_start_time' : datetime
            - 'recent_mistake_rate' : float (0-1)
            - 'avg_engagement_length' : float (minutes)
            - 'preferred_modality' : str ('video', 'quiz', 'text')
            - 'last_intervention' : dict (type and timestamp)
            - 'fatigue_history' : list of (timestamp, estimated_fatigue_level)

    Returns
    -------
    intervention : dict
        {
            'type': str,          # one of ['slow_down', 'take_break', 'switch_modality', 'encourage', 'none']
            'params': dict,       # optional parameters (e.g., break_duration, new_modality)
            'confidence': float   # 0-1
        }
    """

    # 1. Extract current metrics
    typing_speed = real_time_metrics.get('typing_speed', None)
    voice_pitch = real_time_metrics.get('voice_pitch', None)
    sentiment_score = real_time_metrics.get('sentiment_score', 0.0)

    # 2. Extract historical patterns
    mistake_rate = historical_data.get('recent_mistake_rate', 0.0)
    avg_session_length = historical_data.get('avg_engagement_length', 30.0)  # minutes
    preferred_modality = historical_data.get('preferred_modality', 'quiz')
    last_intervention = historical_data.get('last_intervention', None)
    fatigue_history = historical_data.get('fatigue_history', [])

    # 3. Compute derived indicators
    is_early_session = (session_duration < 10)  # assume session_duration computed elsewhere
    is_fatigue_expected = sum(1 for entry in fatigue_history if entry[1] > 0.7) > 2  # example heuristic
    has_recent_intervention = (last_intervention is not None and 
                               (now - last_intervention['timestamp']).total_seconds() < 120)

    # 4. Decision logic (rule-based, can be replaced with ML later)
    # Priority: emotional distress > cognitive overload > boredom > proactive

    # --- Rule 1: Strong negative sentiment + typing hesitation → encourage or break
    if sentiment_score < -0.5 and typing_speed and typing_speed < 20:
        if is_fatigue_expected or mistake_rate > 0.4:
            intervention = {
                'type': 'take_break',
                'params': {'break_duration': 5, 'activity': 'mindful_stretch'}
            }
        else:
            intervention = {
                'type': 'encourage',
                'params': {'message': 'You’re working hard – I see your effort. Let’s try a different angle.'}
            }
        return intervention

    # --- Rule 2: Boredom indicators (very fast typing + constant low difficulty)
    elif typing_speed and typing_speed > 80 and mistake_rate < 0.1 and sentiment_score > 0.3:
        if not has_recent_intervention:
            intervention = {
                'type': 'switch_modality',
                'params': {'new_modality': 'video' if preferred_modality != 'video' else 'quiz'}
            }
        else:
            intervention = {'type': 'none'}
        return intervention

    # --- Rule 3: Cognitive overload (high mistake rate + slow typing + negative sentiment)
    elif mistake_rate > 0.4 and typing_speed and typing_speed < 30 and sentiment_score < -0.2:
        if not has_recent_intervention:
            intervention = {
                'type': 'slow_down',
                'params': {'speed_factor': 0.7, 'offer_hint': True}
            }
        else:
            intervention = {
                'type': 'take_break',
                'params': {'break_duration': 3}
            }
        return intervention

    # --- Rule 4: Proactive fatigue prevention (based on historical session length)
    elif is_fatigue_expected and session_duration > avg_session_length * 1.2:
        intervention = {
            'type': 'take_break',
            'params': {'break_duration': 2, 'activity': 'quick_brain_game'}
        }
        return intervention

    # --- Default: no intervention needed
    return {'type': 'none', 'confidence': 0.9}
