def trigger_emotional_intervention(
    user_id,
    real_time_metrics,
    historical_data,
    consent,
    current_context
):
    """
    Select a minimally intrusive learning-support intervention.

    Inputs:
        user_id: learner identifier
        real_time_metrics: {
            "typing_speed": float | None,
            "voice_pitch": float | None,
            "sentiment_score": float | None,
            "confidence": float  # confidence in the signal estimates
        }
        historical_data: {
            "baseline_typing_speed": float | None,
            "baseline_voice_pitch": float | None,
            "recent_errors": int,
            "recent_pause_count": int,
            "preferred_support_style": str | None,
            "support_cooldown_until": datetime | None
        }
        consent: {
            "affective_support_enabled": bool,
            "voice_analysis_enabled": bool,
            "allow_proactive_prompts": bool
        }
        current_context: {
            "task_type": str,
            "assessment_mode": bool,
            "user_is_speaking": bool,
            "local_time": datetime
        }

    Returns:
        {
            "intervention": str,
            "message": str | None,
            "intensity": str,
            "reason": str,
            "allow_dismiss": bool
        }
    """

    # 1. Respect consent and context boundaries.
    if not consent["affective_support_enabled"]:
        return no_intervention("Affective support is disabled.")

    if current_context["assessment_mode"]:
        return no_intervention(
            "Do not provide emotional coaching during an assessment."
        )

    if (
        historical_data["support_cooldown_until"] is not None
        and current_context["local_time"]
        < historical_data["support_cooldown_until"]
    ):
        return no_intervention("Support cooldown is active.")

    # Do not process voice-derived features without separate consent.
    metrics = dict(real_time_metrics)
    if not consent["voice_analysis_enabled"]:
        metrics["voice_pitch"] = None

    # 2. Require sufficient data and confidence.
    if metrics.get("confidence", 0.0) < 0.70:
        return no_intervention("Signal confidence is too low.")

    # 3. Compare signals with the learner's own baseline.
    baseline_typing = historical_data.get("baseline_typing_speed")
    baseline_pitch = historical_data.get("baseline_voice_pitch")

    typing_change = normalized_change(
        metrics.get("typing_speed"),
        baseline_typing
    )

    pitch_change = normalized_change(
        metrics.get("voice_pitch"),
        baseline_pitch
    )

    sentiment = metrics.get("sentiment_score")
    recent_errors = historical_data.get("recent_errors", 0)
    recent_pauses = historical_data.get("recent_pause_count", 0)

    # 4. Infer only broad learning states, never clinical or personal labels.
    # Require multiple corroborating indicators to reduce false positives.
    possible_strain = (
        sentiment is not None
        and sentiment < -0.55
        and recent_errors >= 2
        and (typing_change < -0.25 or recent_pauses >= 2)
    )

    possible_confusion = (
        recent_errors >= 3
        and recent_pauses >= 2
        and sentiment is not None
        and sentiment < 0.10
    )

    possible_overload = (
        recent_pauses >= 3
        and typing_change < -0.35
    )

    # 5. Choose the least intrusive useful intervention.
    if possible_strain or possible_overload:
        return {
            "intervention": "offer_pause_or_reset",
            "message": (
                "This section looks demanding. Would you like a short pause, "
                "a simpler example, or to continue?"
            ),
            "intensity": "low",
            "reason": "Multiple uncertain indicators suggest the learner may benefit from reduced pressure.",
            "allow_dismiss": True
        }

    if possible_confusion:
        return {
            "intervention": "offer_scaffold",
            "message": (
                "Would you like a hint, a worked example, or to try the problem "
                "a different way?"
            ),
            "intensity": "low",
            "reason": "Recent performance suggests a possible prerequisite or comprehension gap.",
            "allow_dismiss": True
        }

    # 6. Positive support should not interrupt unnecessarily.
    if (
        sentiment is not None
        and sentiment > 0.60
        and recent_errors == 0
        and consent["allow_proactive_prompts"]
    ):
        return {
            "intervention": "brief_progress_feedback",
            "message": "You’re applying that concept consistently. Ready for a slightly harder example?",
            "intensity": "minimal",
            "reason": "Recent performance indicates successful application.",
            "allow_dismiss": True
        }

    return no_intervention("No sufficiently reliable support need detected.")


def normalized_change(current, baseline):
    if current is None or baseline in (None, 0):
        return 0.0
    return (current - baseline) / abs(baseline)


def no_intervention(reason):
    return {
        "intervention": "none",
        "message": None,
        "intensity": "none",
        "reason": reason,
        "allow_dismiss": True
    }
