def select_peer_for_motivation(
    current_user_id,
    user_learning_state,
    peer_database,
    consent,
    policy
):
    """
    Select an anonymized peer example for constructive learning motivation.

    user_learning_state may contain only learner-approved, coarse attributes:
        {
            "mode": "aspiration" | "relatability" | "auto",
            "topic": str,
            "skill_level": float,
            "recent_progress": float,
            "challenge_tags": set[str],
            "preferred_format": str | None
        }

    peer_database contains aggregated or pseudonymized profiles:
        {
            "peer_id": str,
            "topic": str,
            "skill_level": float,
            "progress_pattern": str,
            "challenge_tags": set[str],
            "preferred_format": str | None,
            "consent_to_be_anonymized_example": bool
        }
    """

    # 1. Require explicit opt-in and prevent use in high-stakes contexts.
    if not consent.get("peer_comparison_enabled", False):
        return no_peer("Peer comparison is disabled.")

    if policy.get("high_stakes_context", False):
        return no_peer("Peer comparison is unavailable in this context.")

    state = sanitize_learning_state(user_learning_state)

    # 2. Restrict candidates to consented, anonymized, relevant examples.
    candidates = [
        peer for peer in peer_database
        if peer["peer_id"] != current_user_id
        and peer.get("consent_to_be_anonymized_example", False)
        and peer["topic"] == state["topic"]
        and passes_privacy_threshold(peer, policy)
    ]

    if not candidates:
        return no_peer("No privacy-preserving peer example is available.")

    mode = state.get("mode", "auto")

    if mode == "auto":
        mode = choose_mode_from_learning_signals(state)

    if mode == "aspiration":
        peer = select_aspiration_target(candidates, state, policy)
        if peer is not None:
            return format_peer_result(
                peer=peer,
                intervention="aspiration_target",
                message=(
                    "Here is an anonymized example of a learner who recently "
                    "worked successfully on a slightly more advanced version "
                    "of this skill."
                )
            )

    if mode == "relatability":
        peer = select_relatability_target(candidates, state, policy)
        if peer is not None:
            return format_peer_result(
                peer=peer,
                intervention="relatability_target",
                message=(
                    "Here is an anonymized example from a learner who encountered "
                    "a similar challenge and used a different approach to make progress."
                )
            )

    return no_peer("No suitable constructive comparison was found.")


def select_aspiration_target(candidates, state, policy):
    """
    Prefer a nearby, attainable next-step example—not the highest performer.
    """

    target_level = state["skill_level"] + policy.get("aspiration_gap", 0.10)

    eligible = [
        peer for peer in candidates
        if peer["skill_level"] >= state["skill_level"]
        and peer["skill_level"] <= target_level
        and peer["progress_pattern"] in {
            "steady_progress",
            "overcame_common_obstacle"
        }
    ]

    return max(
        eligible,
        key=lambda peer: (
            similarity(peer.get("challenge_tags", set()),
                       state.get("challenge_tags", set())),
            -abs(peer["skill_level"] - target_level)
        ),
        default=None
    )


def select_relatability_target(candidates, state, policy):
    """
    Prefer similarity of learning challenge and approach, not personal identity.
    """

    eligible = [
        peer for peer in candidates
        if overlap(peer.get("challenge_tags", set()),
                   state.get("challenge_tags", set())) > 0
    ]

    return max(
        eligible,
        key=lambda peer: (
            overlap(peer.get("challenge_tags", set()),
                   state.get("challenge_tags", set())),
            format_match(peer.get("preferred_format"),
                         state.get("preferred_format"))
        ),
        default=None
    )


def choose_mode_from_learning_signals(state):
    # Use learning evidence, not inferred emotion.
    if state.get("recent_progress", 0) < -0.20:
        return "relatability"
    return "aspiration"


def format_peer_result(peer, intervention, message):
    return {
        "intervention": intervention,
        "peer_reference": anonymize(peer),
        "message": message,
        "comparison_basis": "topic, skill level, and learning challenge only",
        "dismissible": True,
        "show_rank": False,
        "show_personal_identity": False
    }


def sanitize_learning_state(state):
    allowed = {
        "mode", "topic", "skill_level", "recent_progress",
        "challenge_tags", "preferred_format"
    }
    return {key: value for key, value in state.items() if key in allowed}


def no_peer(reason):
    return {
        "intervention": "none",
        "peer_reference": None,
        "message": None,
        "reason": reason,
        "dismissible": True
    }
```

