def offer_focus_support(user_id, activity_data, tutor_state, consent):
    """
    Provide optional learning support when in-tutor behavior suggests difficulty.

    Does not inspect browser tabs, URLs, clipboard contents, or other apps.
    Does not block navigation or repeatedly interrupt the learner.
    """

    if not consent.get("focus_support_enabled", False):
        return no_action("Focus support is disabled.")

