        "options": [
            "scaffolding_hint",
            "prerequisite_review",
            "worked_example",
            "independent_attempt",
            "take_a_break"
        ],
        "dismissible": True,
        "cooldown_minutes": 10,
        "reason": "Multiple in-tutor signals suggest the task may be difficult."
    }


