def trigger_emotional_intervention(user_id, real_time_metrics, historical_data):
    """
    Inputs:
        user_id: identifier for the learner
        real_time_metrics: {
            "typing_speed": float | None,
            "voice_pitch": float | None,
            "sentiment_score": float | None,   # e.g. -1.0 to 1.0
            "confidence": float | None          # optional signal quality
        }
        historical_data: {
            "baseline_typing_speed": float | None,
            "baseline_voice_pitch": float | None,
            "recent_error_rate": float | None,
            "recent_session_duration": int | None,
            "preferred_support_style": str | None,
            "consent_for_realtime_signals": bool,
            "consent_for_voice_analysis": bool,
            "quiet_hours": list | None,
            "last_intervention_time": datetime | None,
            "intervention_count_today": int,
            "safety_preferences": dict
        }

    Returns:
        A learner-facing action object, or None.
    """

    # 1. Respect consent, privacy, and safety settings
    if not historical_data.get("consent_for_realtime_signals", False):
        return None

    if real_time_metrics.get("voice_pitch") is not None:
        if not historical_data.get("consent_for_voice_analysis", False):
            real_time_metrics["voice_pitch"] = None

    if is_quiet_hours(historical_data.get("quiet_hours")):
        return None

    if historical_data.get("intervention_count_today", 0) >= MAX_DAILY_INTERVENTIONS:
        return None

    if intervention_cooldown_active(historical_data.get("last_intervention_time")):
        return None

    # 2. Validate and normalize noisy signals
    metrics = validate_metrics(real_time_metrics)

    if metrics.get("confidence", 1.0) < MIN_SIGNAL_CONFIDENCE:
        # Prefer a neutral check-in instead of making an inference
        return make_optional_checkin(
            message="How is this activity feeling so far?",
            choices=["I'm fine", "I need a hint", "I need a short break", "Something else"]
        )

    # Compare signals with the learner's own baseline where available.
    deviations = compare_with_personal_baseline(
        metrics,
        baseline_typing_speed=historical_data.get("baseline_typing_speed"),
        baseline_voice_pitch=historical_data.get("baseline_voice_pitch")
    )

    # 3. Infer only broad learning states, with uncertainty
    # Do not diagnose anxiety, depression, anger, or other mental-health conditions.
    state_scores = {
        "possible_confusion": 0.0,
        "possible_fatigue": 0.0,
        "possible_frustration": 0.0,
        "possible_positive_engagement": 0.0
    }

    if historical_data.get("recent_error_rate", 0) > HIGH_ERROR_RATE:
        state_scores["possible_confusion"] += 0.35

    if deviations.get("typing_speed_drop", 0) > SIGNIFICANT_CHANGE:
        state_scores["possible_fatigue"] += 0.20
        state_scores["possible_confusion"] += 0.15

    if metrics.get("sentiment_score") is not None:
        if metrics["sentiment_score"] < NEGATIVE_SENTIMENT_THRESHOLD:
            state_scores["possible_frustration"] += 0.25
        elif metrics["sentiment_score"] > POSITIVE_SENTIMENT_THRESHOLD:
            state_scores["possible_positive_engagement"] += 0.20

    # Require corroborating evidence before acting.
    state, confidence = select_state_with_uncertainty(state_scores)

    if confidence < MIN_STATE_CONFIDENCE:
        return None

    # 4. Choose the least intrusive intervention that supports autonomy
    preferred_style = historical_data.get("preferred_support_style")

    if state == "possible_confusion":
        return {
            "type": "optional_scaffold",
            "message": "This step can be tricky. Would you like a small hint, a worked example, or to try again independently?",
            "options": ["Small hint", "Worked example", "Try again"],
            "rationale": "Possible difficulty detected; learner chooses the level of help.",
            "follow_up": "fade_scaffolding_after_success",
            "privacy_note": "Based on learning activity, not a diagnosis."
        }

    if state == "possible_fatigue":
        return {
            "type": "break_or_mode_choice",
            "message": "Would you like to continue, switch to a shorter practice item, or take a brief break?",
            "options": ["Continue", "Short practice", "Take a break"],
            "rationale": "Possible reduced focus detected; no pressure to continue."
        }

    if state == "possible_frustration":
        return {
            "type": "de_escalating_checkin",
            "message": "This seems challenging. Would you prefer a simpler example, a hint, or a short reset?",
            "options": ["Simpler example", "Hint", "Short reset", "Keep trying"],
            "rationale": "Offers support without labeling the learner's emotional state."
        }

    if state == "possible_positive_engagement":
        return {
            "type": "reinforce_strategy",
            "message": "You seem to be making good progress. What strategy helped here?",
            "options": ["Reflect", "Continue", "Review the strategy"],
            "rationale": "Reinforces metacognition rather than maximizing session time."
        }

    return None
```

Recommended safeguards:

- Store only the minimum necessary metrics, preferably as short-lived aggregates rather than raw voice recordings.
- Let students disable emotion-related sensing and inspect or delete derived data.
- Never use inferred affect to grade, discipline, target advertising, or restrict access to learning resources.
- Keep interventions sparse and user-dismissable; success should be measured by retention and independent performance, not continued usage.
- Provide a human-support pathway when a student explicitly reports distress or safety concerns, rather than attempting to manage serious mental-health issues through automated inference.
